import { describe, it, expect } from "vitest";
import fs from "node:fs";
import path from "node:path";
import { SPLASH_SCREENS } from "./brand-splash";

/**
 * Brand guard (D-04, 2026-10-27). The app, terav.fit and the ads are one
 * product only while three things hold, and each failed silently before:
 *
 * 1. ONE token file. Both globals.css import brand/tokens.css and redefine
 *    none of its tokens — until today the landing and the app disagreed on
 *    bronze, teal, muted and line with nobody noticing.
 * 2. ONE asset set. Icons, favicons and the wordmark are generated by
 *    dev/scripts/brand/build-brand-assets.mjs into both public folders; a
 *    hand-edited copy in one app is drift.
 * 3. Platform rules: separate `any` and `maskable` icons (never the combined
 *    "any maskable"), and an iOS launch image for every listed iPhone size.
 *
 * Guide: dev/active/brand/brand-guide.md.
 */

const ROOT = path.resolve(__dirname, "../../..");
const read = (p: string) => fs.readFileSync(path.join(ROOT, p), "utf8");
const tokenNames = (css: string) => [...css.matchAll(/^\s*(--[a-z0-9-]+)\s*:/gm)].map((m) => m[1]);

const SHARED = tokenNames(read("brand/tokens.css"));
const SURFACES = ["next-app/src/app/globals.css", "landing/src/app/globals.css"];

describe("one shared token file", () => {
  it("defines the brand tokens", () => {
    for (const t of ["--color-ground", "--color-bronze", "--color-teal", "--color-muted", "--color-line"]) {
      expect(SHARED).toContain(t);
    }
  });

  for (const file of SURFACES) {
    it(`${file} imports brand/tokens.css and redefines none of it`, () => {
      const css = read(file);
      expect(css).toContain('@import "../../../brand/tokens.css";');
      const clash = tokenNames(css).filter((t) => SHARED.includes(t));
      expect(clash, `redefined in ${file}; change brand/tokens.css instead`).toEqual([]);
    });
  }

  it("no surface still hardcodes the retired landing accents", () => {
    const retired = /#(d09a68|e8b988|7fc4d0|a67a4a)\b|208,\s*154,\s*104|127,\s*196,\s*208/i;
    const hits: string[] = [];
    const walk = (dir: string) => {
      for (const e of fs.readdirSync(path.join(ROOT, dir), { withFileTypes: true })) {
        const rel = path.join(dir, e.name);
        if (e.isDirectory()) walk(rel);
        else if (/\.(tsx?|css)$/.test(e.name) && retired.test(read(rel))) hits.push(rel);
      }
    };
    walk("next-app/src");
    walk("landing/src");
    expect(hits).toEqual([]);
  });
});

describe("one generated asset set", () => {
  const SHARED_ASSETS = [
    "favicon.ico", "favicon-16.png", "favicon-32.png", "favicon-48.png", "apple-touch-icon.png",
    "icon-192.png", "icon-512.png", "icon-maskable-192.png", "icon-maskable-512.png",
    "icon.svg", "wordmark.svg", "mark.svg",
  ];
  for (const f of SHARED_ASSETS) {
    it(`${f} is identical in the app and the landing`, () => {
      const a = fs.readFileSync(path.join(ROOT, "next-app/public", f));
      const b = fs.readFileSync(path.join(ROOT, "landing/public", f));
      expect(a.equals(b), `${f} differs; re-run dev/scripts/brand/build-brand-assets.mjs`).toBe(true);
    });
  }

  it("no app/ file-convention icon overrides the generated set", () => {
    // next-app/src/app/favicon.ico (the create-next-app default) shipped from
    // August to 2026-10-27, served next to the real icons; browsers that
    // prefer the .ico showed it instead of Terav's.
    for (const app of ["next-app/src/app", "landing/src/app"]) {
      const conv = fs.readdirSync(path.join(ROOT, app)).filter((f) => /^(favicon|icon|apple-icon)\./.test(f));
      expect(conv, app).toEqual([]);
    }
  });

  it("the public wordmark is the brand/ master", () => {
    expect(read("next-app/public/wordmark.svg")).toBe(read("brand/wordmark.svg"));
  });
});

describe("platform icon rules", () => {
  const manifest = JSON.parse(read("next-app/public/manifest.json")) as {
    background_color: string;
    icons: { src: string; sizes: string; purpose?: string }[];
  };

  it("ships separate any and maskable icons at 192 and 512, never combined", () => {
    for (const purpose of ["any", "maskable"]) {
      const sizes = manifest.icons.filter((i) => i.purpose === purpose).map((i) => i.sizes).sort();
      expect(sizes, purpose).toEqual(["192x192", "512x512"]);
    }
    expect(manifest.icons.every((i) => i.purpose === "any" || i.purpose === "maskable")).toBe(true);
    for (const i of manifest.icons) expect(fs.existsSync(path.join(ROOT, "next-app/public", i.src))).toBe(true);
  });

  it("splash background matches the ground token", () => {
    expect(manifest.background_color).toBe("#0e0f12");
    expect(read("brand/tokens.css")).toContain("--color-ground: #0e0f12;");
  });

  it("every iOS launch image exists at the size its media query names", () => {
    expect(SPLASH_SCREENS.length).toBeGreaterThanOrEqual(10);
    for (const s of SPLASH_SCREENS) {
      const png = fs.readFileSync(path.join(ROOT, "next-app/public", s.url));
      const [w, h] = [png.readUInt32BE(16), png.readUInt32BE(20)];
      const m = s.media.match(/device-width: (\d+)px\) and \(device-height: (\d+)px\) and \(-webkit-device-pixel-ratio: (\d)/)!;
      expect([w, h], s.url).toEqual([+m[1] * +m[3], +m[2] * +m[3]]);
    }
  });
});
